{
  "passageId": "law-interpretation-guarantee",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법의 보편적 적용이라는 성질을 근거로 일상적 의미에 충실하게 해석해야 한다는 당위를 도출한다."
    },
    {
      "id": "R2",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "일상적 의미에 충실한 해석을 문리 해석이라고 명명하고 그 위상을 밝힌다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "문리 해석만으로 내용을 파악하기 어렵다는 한계에 대응하여 체계적·역사적 해석이라는 대안이 제시된다."
    },
    {
      "id": "R4",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "해석에 활용하는 자료라는 같은 기준에서 사용 맥락과 입법 과정의 논의라는 차이를 보여 준다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "구조물의 안전을 담보한다는 용례가 담보의 일상적 의미를 구체적으로 보여 준다."
    },
    {
      "id": "R6",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "일상적 사용과 성문법 조문에서의 사용이라는 서로 다른 맥락에서 담보의 의미가 달라짐을 대비한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유상 계약에서의 값어치 보장은 법적 맥락에 따라 달라지는 담보 의미의 구체적 사례이다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "채권 실현 가능성을 보장하는 조치는 법적 맥락에 따라 달라지는 담보 의미의 구체적 사례이다."
    },
    {
      "id": "R9",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "유상 계약과 채권이라는 두 맥락에서 담보가 보장하는 대상과 의미가 서로 다르다."
    },
    {
      "id": "R10",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "매매 계약을 유상 계약에 속하는 하위 유형으로 명시한다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "거래 대상의 값어치 보장이라는 담보의 의미를 매매 목적물의 하자에 대한 책임으로 구체화한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "매도인이 부담하는 담보 책임의 구체적 내용을 손해 배상과 계약 파기·환불로 풀어 설명한다."
    },
    {
      "id": "R13",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "손해 배상이라는 원칙에 대해 계약 목적을 달성할 수 없는 경우의 예외적 구제를 제시한다."
    },
    {
      "id": "R14",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "매도인의 담보 책임 인정 원칙에 매수인이 하자를 알았거나 알 수 있었던 경우라는 예외를 둔다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보 물권을 채권 실현 가능성을 보장하는 조치의 구체적 예로 제시한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "돈을 받아야 금전 채권이 실현된다는 사실이 미지급 시 강제 집행을 거쳐야 한다는 설명을 뒷받침한다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "강제 집행 절차를 목적물이 부동산인 경우의 경매와 배당으로 구체화한다."
    },
    {
      "id": "R18",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "채권액에 비례한 배당 원칙에 대해 담보 물권자의 우선 배당이라는 예외를 제시한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보 물권자의 우선 배당은 채권 실현 가능성을 보장하는 조치가 어떻게 작동하는지 보여 주는 구체적 사례이다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증을 담보 기능을 수행하는 구체적 사례로 연결하여 채권 맥락의 담보 설명을 확장한다."
    },
    {
      "id": "R21",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "보증에 등장하는 사람과 그들이 부담하는 채무를 주채무자·보증인·주채무·보증 채무로 명명한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증이 담보 기능을 수행한다는 성질로부터 주채무 소멸 시 보증 채무도 소멸한다는 법적 설명을 도출한다."
    },
    {
      "id": "R23",
      "type": "CONDITION",
      "otherName": "",
      "reason": "채권자와 보증인 사이의 보증 계약을 보증 성립에 필요한 조건으로 제시한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증인에게만 채무가 발생한다는 사실을 근거로 보증 계약이 유상 계약이 아니라고 판단한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "서로 대가를 주고받기로 한다는 유상 계약의 정의가 보증 계약의 해당 여부를 판단하는 근거가 된다."
    },
    {
      "id": "R26",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "별도의 대가 지급 계약이 있더라도 보증 계약 자체는 유상 계약이 아니라는 판단이 유지된다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "민법상 계약서와 서명 등의 요건 및 위반 효과가 보증인 보호를 위한 법적 규제의 구체적 내용이다."
    },
    {
      "id": "R28",
      "type": "CONDITION",
      "otherName": "",
      "reason": "계약서와 서명 또는 기명 날인이라는 형식 요건의 위반을 계약 무효의 조건으로 제시한다."
    },
    {
      "id": "R29",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "형식 요건을 위반한 계약은 무효이지만 이미 이행한 경우에는 무효를 주장할 수 없다는 한계를 둔다."
    },
    {
      "id": "R30",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "민법상 보증인 보호 규제에서 일정한 경우에 추가되는 특별법상 보호로 논의를 넓힌다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증 기간 미명시 시 3년으로 간주하는 규정을 특별법상 보호의 구체적 예로 제시한다."
    },
    {
      "id": "R32",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "보증인에게 이행 거절권이 인정되지만 연대 보증 특약으로 그 권리를 포기할 수 있다는 예외를 제시한다."
    },
    {
      "id": "R33",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "연대 보증 특약이 이행 거절권의 포기라는 내용으로부터 연대 보증인은 직접 청구를 거절할 수 없다는 설명이 따른다."
    },
    {
      "id": "R34",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "일반 보증인과 연대 보증인이라는 서로 다른 대상을 이행 거절 가능 여부라는 같은 기준으로 대비한다."
    },
    {
      "id": "R35",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "특별법에 따른 보증인 보호 설명에서 그 보호가 연대 보증인에게도 적용되는지의 쟁점으로 논의를 옮긴다."
    },
    {
      "id": "R36",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "연대 보증인의 법적 성질을 설명한 뒤 연대 보증인에 대한 특별법 적용 여부라는 새 문제로 넘어간다."
    },
    {
      "id": "R37",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "같은 법률 안에서 조문의 적용 대상 규정과 입법 과정의 연대 보증인 보호 취지 사이에 어긋남이 제시된다."
    },
    {
      "id": "R38",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "조문 내용과 입법 과정의 논의가 일치하지 않는다는 점이 해석 방법에 따라 결론이 달라질 수 있다는 판단을 뒷받침한다."
    },
    {
      "id": "R39",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 문리 해석 방법을 특별법 제2조의 보증 계약 문구를 검토하는 구체적 사례에 연결한다."
    },
    {
      "id": "R40",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "입법 과정의 논의를 살피는 역사적 해석 방법을 특별법의 연대 보증인 보호 취지에 가져다 쓴다."
    }
  ]
}

